protected function shouldBeExcluded($attribute)
{
    foreach ($this->excludeAttributes as $excludeAttribute) {
        if ($attribute === $excludeAttribute ||
            Str::startsWith($attribute, $excludeAttribute.'.')) {
            return true;
        }
    }

    return false;
}

/**
